const estilo=document.createElement('link');
estilo.rel='stylesheet';
estilo.href='/css/presidencia.css?v=20260917pr2';
document.head.append(estilo);

const registros=[
 {nome:'Luiz Inácio Lula da Silva',apelido:'Lula',atual:true,aliases:['lula','luiz inacio lula da silva','presidente atual','atual'],periodos:['01/01/2003 a 31/12/2010','desde 01/01/2023'],vice:'Geraldo Alckmin no mandato atual',nota:'Presidente da República no mandato iniciado em 1º de janeiro de 2023.',fontes:[['Planalto','https://www.gov.br/planalto/pt-br'],['Acervo presidencial','https://www.gov.br/secretariageral/pt-br/centrais-de-conteudo/biblioteca-da-pr/galeria-dos-ex-presidentes/luiz-inacio-lula-da-silva']]},
 {nome:'Jair Messias Bolsonaro',apelido:'Jair Bolsonaro',aliases:['jair','bolsonaro','jair bolsonaro'],periodos:['01/01/2019 a 31/12/2022'],vice:'Hamilton Mourão',nota:'Ex-presidente da República.',fontes:[['Acervo presidencial','https://www.biblioteca.presidencia.gov.br/presidencia/ex-presidentes/bolsonaro/Bolsonaro']]},
 {nome:'Michel Miguel Elias Temer Lulia',apelido:'Michel Temer',aliases:['michel temer','temer'],periodos:['Presidente em exercício: 12/05/2016 a 31/08/2016','Presidente da República: 31/08/2016 a 31/12/2018'],vice:'Cargo de vice-presidente vago durante a Presidência definitiva',nota:'Ex-presidente da República.',fontes:[['Acervo presidencial','https://www.gov.br/secretariageral/pt-br/centrais-de-conteudo/biblioteca-da-pr/galeria-dos-ex-presidentes/capa-dados-ex-presidente']]},
 {nome:'Dilma Vana Rousseff',apelido:'Dilma Rousseff',aliases:['dilma','dilma rousseff'],periodos:['01/01/2011 a 31/12/2014','01/01/2015 a 31/08/2016'],vice:'Michel Temer',nota:'Ex-presidenta da República. O mandato foi encerrado em 31 de agosto de 2016 após julgamento do processo de impeachment pelo Senado.',fontes:[['Acervo presidencial','https://www.gov.br/secretariageral/pt-br/centrais-de-conteudo/biblioteca-da-pr/galeria-dos-ex-presidentes/dilma-vana-rousseff']]},
 {nome:'Fernando Henrique Cardoso',apelido:'Fernando Henrique Cardoso',aliases:['fhc','fernando henrique','fernando henrique cardoso'],periodos:['01/01/1995 a 31/12/1998','01/01/1999 a 31/12/2002'],vice:'Marco Maciel',nota:'Ex-presidente da República.',fontes:[['Acervo presidencial','https://www.gov.br/secretariageral/pt-br/centrais-de-conteudo/biblioteca-da-pr/galeria-dos-ex-presidentes/fernando-henrique-cardoso']]},
 {nome:'Itamar Augusto Cautiero Franco',apelido:'Itamar Franco',aliases:['itamar','itamar franco'],periodos:['Empossado na Presidência em 29/12/1992','Governo até 31/12/1994'],vice:'Cargo de vice-presidente vago após a sucessão',nota:'Ex-presidente da República.',fontes:[['Acervo presidencial','https://www.gov.br/secretariageral/pt-br/centrais-de-conteudo/biblioteca-da-pr/galeria-dos-ex-presidentes/itamar-augusto-cautiero-franco']]},
 {nome:'Fernando Affonso Collor de Mello',apelido:'Fernando Collor',aliases:['collor','fernando collor','fernando collor de mello'],periodos:['Posse em 15/03/1990','Afastado em 02/10/1992','Renúncia em 29/12/1992'],vice:'Itamar Franco',nota:'Ex-presidente da República.',fontes:[['Acervo presidencial','https://www.gov.br/secretariageral/pt-br/centrais-de-conteudo/biblioteca-da-pr/galeria-dos-ex-presidentes/collor']]},
 {nome:'José Sarney',apelido:'José Sarney',aliases:['sarney','jose sarney'],periodos:['15/03/1985 a 15/03/1990'],vice:'Cargo de vice-presidente vago após a sucessão',nota:'Ex-presidente da República.',fontes:[['Acervo presidencial','https://www.gov.br/secretariageral/pt-br/centrais-de-conteudo/biblioteca-da-pr/galeria-dos-ex-presidentes/jose_sarney']]}
];

const links={
 legislacao:'https://www4.planalto.gov.br/legislacao/portal-legis/busca-avancada',
 stf:'https://portal.stf.jus.br/processos/',
 stj:'https://www.stj.jus.br/sites/portalp/Processos/Consulta-Processual/',
 tse:'https://www.tse.jus.br/servicos-judiciais/processos/pje',
 cnj:'https://www.cnj.jus.br/sistemas/datajud/api-publica/',
 dou:'https://www.in.gov.br/consulta',
 inlabs:'https://inlabs.in.gov.br/'
};
const normalizar=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const escapar=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let presidenteAtivo=null,processosCache=new Map();

function resultados(q){
 const n=normalizar(q);
 if(!n||n==='presidente'||n==='presidente atual'||n==='atual')return registros.filter(x=>x.atual);
 if(n==='ex presidente'||n==='ex presidentes'||n==='ex-presidente'||n==='ex-presidentes')return registros.filter(x=>!x.atual);
 return registros.filter(x=>normalizar([x.nome,x.apelido,...x.aliases].join(' ')).includes(n));
}
function cartao(p){
 return `<article class="presidencia-cartao ${p.atual?'atual':''}">
  <header><div><span class="rotulo">${p.atual?'PRESIDENTE DA REPÚBLICA · ATUAL':'REGISTRO DE EX-PRESIDENTE'}</span><h4>${escapar(p.nome)}</h4>${p.apelido!==p.nome?`<small>${escapar(p.apelido)}</small>`:''}</div>${p.atual?'<b class="presidencia-selo">MANDATO ATUAL</b>':''}</header>
  <div class="presidencia-dados"><div><small>Período(s)</small>${p.periodos.map(x=>`<span>${escapar(x)}</span>`).join('')}</div><div><small>Vice-Presidência</small><span>${escapar(p.vice)}</span></div></div>
  <p>${escapar(p.nota)}</p>
  <div class="presidencia-acoes"><button data-abrir-dossie="${escapar(p.nome)}">Abrir dossiê documental</button>${p.fontes.map(([nome,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${escapar(nome)} ↗</a>`).join('')}</div>
 </article>`;
}
function encontrar(nome){return registros.find(x=>x.nome===nome)||null}
function cabecalhoDossie(p){return `<header class="dossie-cabecalho"><div><span class="rotulo">DOSSIÊ DOCUMENTAL · FONTES OFICIAIS</span><h3>${escapar(p.nome)}</h3><p>O dossiê separa fatos documentais, andamento processual e disponibilidade de íntegra. Investigação, ação ou processo não equivalem automaticamente a condenação.</p></div><button data-fechar-dossie aria-label="Fechar dossiê">×</button></header><nav class="dossie-abas"><button data-dossie-aba="processos" class="ativo">Processos</button><button data-dossie-aba="atos">Leis & atos</button><button data-dossie-aba="documentos">PDFs & documentos</button><button data-dossie-aba="mandato">Mandatos</button><button data-dossie-aba="fontes">Fontes</button></nav><section id="dossie-conteudo" class="dossie-conteudo"></section>`}
function abrirDossie(p){presidenteAtivo=p;let d=document.querySelector('#presidencia-dossie');if(!d){d=document.createElement('section');d.id='presidencia-dossie';d.className='presidencia-dossie';document.querySelector('.presidencia-area')?.append(d)}d.innerHTML=cabecalhoDossie(p);d.querySelector('[data-fechar-dossie]')?.addEventListener('click',()=>d.remove());d.querySelectorAll('[data-dossie-aba]').forEach(b=>b.addEventListener('click',()=>mostrarAbaDossie(b.dataset.dossieAba,b)));mostrarAbaDossie('processos',d.querySelector('[data-dossie-aba="processos"]'));d.scrollIntoView({behavior:'smooth',block:'start'})}
function ativarAba(botao){const d=document.querySelector('#presidencia-dossie');d?.querySelectorAll('[data-dossie-aba]').forEach(x=>x.classList.toggle('ativo',x===botao))}
function mostrarAbaDossie(aba,botao){ativarAba(botao);if(!presidenteAtivo)return;if(aba==='processos')renderProcessos(presidenteAtivo);if(aba==='atos')renderAtos(presidenteAtivo);if(aba==='documentos')renderDocumentos(presidenteAtivo);if(aba==='mandato')renderMandato(presidenteAtivo);if(aba==='fontes')renderFontes(presidenteAtivo)}
async function carregarProcessos(p){if(processosCache.has(p.nome))return processosCache.get(p.nome);const r=await fetch(`/api/observatorio-politico?modo=stf-parte&nome=${encodeURIComponent(p.nome)}`);const d=await r.json();if(!r.ok)throw new Error(d.erro||'Falha na consulta');processosCache.set(p.nome,d);return d}
function linhaProcesso(x){const status=x.tramite?'EM TRAMITAÇÃO':'FORA DE TRAMITAÇÃO';return `<article class="dossie-processo"><div><span class="dossie-status ${x.tramite?'andamento':'encerrado'}">${status}</span><h4>${escapar((x.classe?x.classe+' ':'')+x.numero)}</h4><p>${escapar(x.nome||'Registro processual público')}</p></div><div class="dossie-links"><a href="${x.url}" target="_blank" rel="noopener noreferrer">Processo oficial ↗</a><a href="${x.inteiroTeor}" target="_blank" rel="noopener noreferrer">Acórdão / PDF oficial ↗</a></div></article>`}
async function renderProcessos(p){const area=document.querySelector('#dossie-conteudo');if(!area)return;area.innerHTML='<div class="dossie-carregando">Consultando processos públicos pelo nome exato no STF…</div>';try{const d=await carregarProcessos(p),itens=d.dados||[];area.innerHTML=`<div class="dossie-resumo"><div><small>STF · resultados automáticos</small><strong>${itens.length}</strong></div><p>${escapar(d.aviso||'')}</p></div><div class="dossie-lista">${itens.length?itens.map(linhaProcesso).join(''):'<div class="obs-vazio">Nenhum processo foi extraído automaticamente nesta tentativa. Use as consultas oficiais abaixo para conferir diretamente na fonte.</div>'}</div><section class="dossie-complementar"><h4>Consultas oficiais complementares</h4><div class="dossie-fontes-grid"><a href="${d.consultas?.emTramitacao||links.stf}" target="_blank" rel="noopener noreferrer"><b>STF · em tramitação</b><span>Pesquisa oficial pelo nome da parte.</span></a><a href="${d.consultas?.encerrados||links.stf}" target="_blank" rel="noopener noreferrer"><b>STF · fora de tramitação</b><span>Confere registros que já não estão em andamento.</span></a><a href="${links.stj}" target="_blank" rel="noopener noreferrer"><b>STJ · consulta processual</b><span>Pesquisa avançada por nome da parte e decisões públicas.</span></a><a href="${links.tse}" target="_blank" rel="noopener noreferrer"><b>TSE · PJe público</b><span>Processos públicos eleitorais, inclusive pesquisa por nome da parte.</span></a><a href="${links.cnj}" target="_blank" rel="noopener noreferrer"><b>CNJ · DataJud</b><span>Metadados nacionais; a Biblioteca consulta por número processual para evitar homônimos.</span></a></div><div class="dossie-aviso"><b>Por que alguns processos não aparecem aqui?</b><p>Segredo de justiça, sigilo, grafia diferente do nome, limites da pesquisa por parte e ausência de API pública para busca nominal em alguns tribunais. O item não é tratado como inexistente apenas porque não pôde ser incorporado.</p></div></section>`}catch{area.innerHTML=`<div class="obs-vazio">A consulta automática do STF não respondeu. A pesquisa oficial continua disponível.</div><div class="dossie-fontes-grid"><a href="${links.stf}" target="_blank" rel="noopener noreferrer">Abrir consulta do STF ↗</a><a href="${links.stj}" target="_blank" rel="noopener noreferrer">Abrir consulta do STJ ↗</a><a href="${links.tse}" target="_blank" rel="noopener noreferrer">Abrir PJe/TSE ↗</a></div>`}}
function renderAtos(p){const area=document.querySelector('#dossie-conteudo');area.innerHTML=`<div class="dossie-bloco"><span class="rotulo">BASE DA LEGISLAÇÃO FEDERAL</span><h4>Leis, decretos, medidas provisórias, vetos e outros atos</h4><p>A base oficial do Planalto permite filtrar pelo Presidente da República e pelo responsável pela assinatura. Use o nome completo abaixo para não misturar homônimos.</p><div class="dossie-copia"><code>${escapar(p.nome)}</code><button data-copiar-presidente>Copiar nome</button></div><div class="dossie-fontes-grid"><a href="${links.legislacao}" target="_blank" rel="noopener noreferrer"><b>Pesquisa avançada do Planalto</b><span>Filtre “Presidente da República” ou “Presidente em exercício”.</span></a><a href="${links.dou}" target="_blank" rel="noopener noreferrer"><b>Diário Oficial da União</b><span>Publicações oficiais e atos publicados.</span></a></div><div class="dossie-aviso"><b>“Lei aprovada pelo presidente”</b><p>A interface usa termos documentais: lei sancionada/promulgada, veto, decreto ou medida provisória. A aprovação legislativa é do Congresso; o Presidente pode sancionar ou vetar projetos e expedir atos nas hipóteses constitucionais.</p></div></div>`;area.querySelector('[data-copiar-presidente]')?.addEventListener('click',async e=>{try{await navigator.clipboard.writeText(p.nome);e.currentTarget.textContent='Copiado'}catch{e.currentTarget.textContent=p.nome}})}
async function renderDocumentos(p){const area=document.querySelector('#dossie-conteudo');area.innerHTML='<div class="dossie-carregando">Montando índice documental…</div>';let proc=null;try{proc=await carregarProcessos(p)}catch{}const itens=proc?.dados||[];area.innerHTML=`<div class="dossie-bloco"><span class="rotulo">PDFS E ÍNTEGRAS OFICIAIS</span><h4>Arquivos que podem ser baixados ou consultados na origem</h4><div class="dossie-documentos"><div><b>Acervo presidencial</b><p>Documentos históricos e registros institucionais preservados pela Presidência.</p>${p.fontes.map(([n,u])=>`<a href="${u}" target="_blank" rel="noopener noreferrer">${escapar(n)} ↗</a>`).join('')}</div><div><b>Acórdãos do STF</b><p>Cada processo abaixo abre a base de inteiro teor. Quando o acórdão estiver publicado, o STF disponibiliza a íntegra correspondente.</p>${itens.slice(0,30).map(x=>`<a href="${x.inteiroTeor}" target="_blank" rel="noopener noreferrer">${escapar((x.classe?x.classe+' ':'')+x.numero)} · PDF/inteiro teor ↗</a>`).join('')||'<span>Nenhum processo foi indexado automaticamente nesta tentativa.</span>'}</div><div><b>Diário Oficial da União</b><p>A Imprensa Nacional mantém publicações certificadas e também disponibiliza edições em PDF.</p><a href="${links.dou}" target="_blank" rel="noopener noreferrer">Pesquisar DOU ↗</a><a href="${links.inlabs}" target="_blank" rel="noopener noreferrer">INLABS · PDFs e dados abertos ↗</a></div></div><div class="dossie-legenda-pdf"><span><i class="pdf-ok"></i> PDF/íntegra disponível quando a fonte publica o arquivo</span><span><i class="pdf-link"></i> apenas consulta oficial quando não há arquivo público incorporável</span><span><i class="pdf-bloqueado"></i> restrito/sigiloso quando a lei ou o tribunal impede acesso público</span></div></div>`}
function renderMandato(p){const area=document.querySelector('#dossie-conteudo');area.innerHTML=`<div class="dossie-bloco"><span class="rotulo">MANDATOS E SUCESSÃO</span><h4>${escapar(p.nome)}</h4><div class="presidencia-dados dossie-mandato"><div><small>Período(s)</small>${p.periodos.map(x=>`<span>${escapar(x)}</span>`).join('')}</div><div><small>Vice-Presidência</small><span>${escapar(p.vice)}</span></div></div><p>${escapar(p.nota)}</p></div>`}
function renderFontes(p){const area=document.querySelector('#dossie-conteudo');area.innerHTML=`<div class="dossie-bloco"><span class="rotulo">RASTREABILIDADE</span><h4>De onde cada informação deve vir</h4><div class="dossie-fontes-grid">${p.fontes.map(([n,u])=>`<a href="${u}" target="_blank" rel="noopener noreferrer"><b>${escapar(n)}</b><span>Registro institucional da Presidência.</span></a>`).join('')}<a href="${links.legislacao}" target="_blank" rel="noopener noreferrer"><b>Planalto · Legislação</b><span>Leis, decretos, MPs, vetos e situação dos atos.</span></a><a href="${links.stf}" target="_blank" rel="noopener noreferrer"><b>STF</b><span>Processos, partes, decisões e inteiro teor publicado.</span></a><a href="${links.stj}" target="_blank" rel="noopener noreferrer"><b>STJ</b><span>Consulta processual e decisões públicas.</span></a><a href="${links.tse}" target="_blank" rel="noopener noreferrer"><b>TSE · PJe</b><span>Consulta pública da Justiça Eleitoral.</span></a><a href="${links.cnj}" target="_blank" rel="noopener noreferrer"><b>CNJ · DataJud</b><span>Metadados processuais nacionais, respeitando sigilo e proteção de dados.</span></a><a href="${links.dou}" target="_blank" rel="noopener noreferrer"><b>Diário Oficial da União</b><span>Publicação oficial de atos.</span></a></div></div>`}

function renderizar(q='presidente atual'){
 const area=document.querySelector('#observatorio-conteudo');
 if(!area)return;
 const itens=resultados(q);
 area.innerHTML=`<div class="presidencia-area"><section class="presidencia-busca"><span class="rotulo">PRESIDÊNCIA DA REPÚBLICA</span><h3>Pesquise o presidente ou um ex-presidente.</h3><p>Além do perfil institucional, abra o dossiê para consultar processos públicos, leis e atos, PDFs e fontes oficiais.</p><form id="form-presidencia" class="obs-form"><input id="campo-presidencia" type="search" value="${escapar(q==='presidente atual'?'':q)}" placeholder="Ex.: Lula, Bolsonaro, Dilma, FHC, Sarney…"><button class="primario">Pesquisar</button></form><div class="presidencia-rapida"><button data-presidente-rapido="presidente atual">Atual</button><button data-presidente-rapido="Lula">Lula</button><button data-presidente-rapido="Bolsonaro">Bolsonaro</button><button data-presidente-rapido="Dilma">Dilma</button><button data-presidente-rapido="FHC">FHC</button><button data-presidente-rapido="ex-presidentes">Ex-presidentes</button></div></section><section id="resultado-presidencia" class="presidencia-resultados">${itens.length?itens.map(cartao).join(''):'<div class="obs-vazio">Nenhum presidente deste recorte foi encontrado. Esta versão cobre presidentes desde 1985.</div>'}</section><div class="presidencia-nota">O dossiê nunca converte denúncia, investigação ou processo em “crime cometido”. Ele mostra o que a fonte oficial registra e o estado documental disponível.</div></div>`;
 const form=document.querySelector('#form-presidencia');
 form?.addEventListener('submit',e=>{e.preventDefault();const q2=document.querySelector('#campo-presidencia')?.value||'';renderizar(q2);const unicos=resultados(q2);if(unicos.length===1)setTimeout(()=>abrirDossie(unicos[0]),0)});
 document.querySelectorAll('[data-presidente-rapido]').forEach(b=>b.addEventListener('click',()=>{const q2=b.dataset.presidenteRapido;renderizar(q2);const unicos=resultados(q2);if(unicos.length===1)setTimeout(()=>abrirDossie(unicos[0]),0)}));
 document.querySelectorAll('[data-abrir-dossie]').forEach(b=>b.addEventListener('click',()=>{const p=encontrar(b.dataset.abrirDossie);if(p)abrirDossie(p)}));
 if(itens.length===1&&q!=='presidente atual')setTimeout(()=>abrirDossie(itens[0]),0);
}
function instalar(){
 const dialogo=document.querySelector('#observatorio-politico');
 const abas=dialogo?.querySelector('.observatorio-abas');
 if(!abas||abas.querySelector('[data-obs-aba="presidencia"]'))return Boolean(abas);
 const botao=document.createElement('button');botao.dataset.obsAba='presidencia';botao.textContent='Presidência';const referencia=abas.querySelector('[data-obs-aba="parlamentares"]');referencia?.before(botao);botao.addEventListener('click',()=>{abas.querySelectorAll('[data-obs-aba]').forEach(x=>x.classList.toggle('ativo',x===botao));renderizar()});return true;
}
if(!instalar()){const observador=new MutationObserver(()=>{if(instalar())observador.disconnect()});observador.observe(document.body,{childList:true,subtree:true})}
